questions.question:
解释浏览器事件循环宏任务/微任务机制，并说明下面代码的输出顺序及原因：
console.log(1);
setTimeout(() => console.log(2), 0);
Promise.resolve().then(() => console.log(3));
console.log(4);

questions.test:
const calls = [];
const f = debounce((x) => calls.push(x), 100);
f(1); f(2); f(3); f(4); f(5);
setTimeout(() => {
  if (calls.length !== 1) { console.error('debounce fail: 触发' + calls.length + '次'); process.exit(1); }
  if (calls[0] !== 5) { console.error('debounce fail: 应传最后一次参数' + calls[0]); process.exit(1); }
  console.log('PASS');
}, 300);

let count = 0;
const f = throttle(() => count++, 200);
const t = setInterval(f, 30);
setTimeout(() => {
  clearInterval(t);
  if (count < 2 || count > 7) { console.error('throttle fail: ' + count + '次'); process.exit(1); }
  console.log('PASS');
}, 1000);

const a = { x: 1, arr: [1, { y: 2 }], d: new Date(123) };
const b = deepClone(a);
if (b === a) { console.error('fail: 返回了原对象'); process.exit(1); }
a.arr[1].y = 999;
if (b.arr[1].y !== 2) { console.error('fail: 不是深拷贝'); process.exit(1); }
if (!(b.d instanceof Date) || b.d.getTime() !== 123) { console.error('fail: Date 处理'); process.exit(1); }
const c = {}; c.self = c;
try {
  const d = deepClone(c);
  if (d.self !== d) { console.error('fail: 循环引用结果不对'); process.exit(1); }
} catch (e) { console.error('fail: 循环引用崩溃 ' + e.message); process.exit(1); }
console.log('PASS');

promiseAll([Promise.resolve(1), new Promise((res) => setTimeout(() => res(2), 10))]).then((v) => {
  if (v.join(',') !== '1,2') { console.error('fail: 结果 ' + v.join(',')); process.exit(1); }
  return promiseAll([Promise.resolve(1), Promise.reject(new Error('x'))]).then(
    () => { console.error('fail: 应 reject'); process.exit(1); },
    () => { console.log('PASS'); }
  );
}).catch((e) => { console.error('crash: ' + e.message); process.exit(1); });
